"""Build bilingual original noise algebra lab, offline packet and source readers."""
from pathlib import Path
from html import escape
import json,zipfile
from build_bpe_lab import prose
FILES=('core.py','fixtures.json','demo.py','test_core.py','README-zh.md','README-en.md','WORKSHEET-zh.md','WORKSHEET-en.md','REFERENCE-zh.md','REFERENCE-en.md','SOURCES.md')
IDS=('contract','worked','run','transfer','finish')
def render(root):
 source=root/'learning/diffusion-noise';web=root/'web'
 fixtures=json.loads((source/'fixtures.json').read_text())
 (web/'diffusion-noise-fixtures.js').write_text('globalThis.ModelAtlasDiffusionFixtures='+json.dumps(fixtures,separators=(',',':'))+';\n')
 with zipfile.ZipFile(web/'diffusion-noise-lab.zip','w',zipfile.ZIP_DEFLATED) as z:
  for name in FILES:
   info=zipfile.ZipInfo('diffusion-noise/'+name,(2026,11,2,0,0,0));info.compress_type=zipfile.ZIP_DEFLATED;z.writestr(info,(source/name).read_bytes())
 for name in FILES:(web/('diffusion-noise-'+name)).write_bytes((source/name).read_bytes())
 for lang in ('zh','en'):
  en=lang=='en';suffix='-en' if en else ''
  def t(zh,english):return english if en else zh
  title=t('扩散噪声与预测误差','Diffusion noise and prediction error');chunks=(source/f'README-{lang}.md').read_text().split('\n## ')
  sections={}
  for identity,chunk in zip(IDS,chunks[1:]):
   heading,body=chunk.split('\n',1);sections[identity]=f'<section id="{identity}"><h2>{escape(heading)}</h2>{prose(body)}</section>'
  outputs=[('alpha_bar','本次 a','Current a'),('estimate','本次估计','Current estimate'),('signal_coefficient','信号系数','Signal coefficient'),('noise_coefficient','噪声系数','Noise coefficient'),('signal','信号项','Signal term'),('noise','噪声项','Noise term'),('xt','带噪信号 xt','Noisy signal xt'),('oracle','已知噪声反解','Oracle inversion'),('predicted','给定估计反解','Supplied-estimate inversion'),('error','逐维误差','Coordinate error'),('amplification','误差幅度放大系数','Error-amplitude factor'),('estimate_mse','噪声估计 MSE','Noise-estimate MSE'),('mse','重建 MSE','Reconstruction MSE'),('expected_mse','恒等式预期 MSE','MSE from identity')]
  cards=''.join(f'<div><dt>{t(zh,english)}</dt><dd id="out-{key}"></dd></div>' for key,zh,english in outputs)
  controls=f'''<section id="interactive"><h2>{t('亲手计算：先预测，再点击','Calculate it: predict before clicking')}</h2><p>{t('更改输入会隐藏旧结果。T 预设只加载输入；点击计算才揭晓。a 滑块与数值框同步；范围只是教学护栏。','Edits hide old results. The T preset only loads inputs; Calculate reveals the result. The a slider and number field stay synchronized; bounds are teaching guardrails.')}</p><div class="noise-controls"><label for="preset">{t('原创输入预设','Original input preset')}<select id="preset"><option value="worked">W · {t('跟做','Worked')}</option><option value="high">{t('高噪声，同一估计误差','High noise, same estimate error')}</option><option value="transfer">T · {t('独立迁移','Independent transfer')}</option></select></label><label for="alpha">alpha_bar · [0.01, 1]<input id="alpha" type="number" min="0.01" max="1" step="any" aria-describedby="input-error"></label><label for="alpha-slider">{t('调节累计 alpha','Adjust cumulative alpha')}<input id="alpha-slider" type="range" min="0.01" max="1" step="any"></label><label for="estimate-0">epsilon_hat[0] · [-10, 10]<input id="estimate-0" type="number" min="-10" max="10" step="any" aria-describedby="input-error"></label><label for="estimate-1">epsilon_hat[1] · [-10, 10]<input id="estimate-1" type="number" min="-10" max="10" step="any" aria-describedby="input-error"></label><button id="calculate" type="button">{t('计算','Calculate')}</button><button id="reset" type="button">{t('重置为 W','Reset to W')}</button></div><p id="fixture-context"></p><p id="input-error" role="alert"></p><p id="calculation-status" role="status" aria-live="polite"></p><div id="result" hidden><p class="warning">{t('当前估计由你给定，不是模型预测。MSE 对照已知教学信号，不代表图像或视频质量。','You supplied the estimate; no model predicted it. MSE compares to a known teaching signal, not image/video quality.')}</p><dl class="result-grid">{cards}</dl></div><noscript><p>{t('交互需 JavaScript。下方 Python 下载和上方完整推导仍可使用。','Interaction requires JavaScript. The full trace above and Python download below remain usable.')}</p></noscript></section>'''
  reference=escape((source/f'REFERENCE-{lang}.md').read_text());links=''.join(f'<li><a href="diffusion-noise-{n}">{n}</a> · <a href="#source-{n}">{t("检查源码","Inspect source")}</a></li>' for n in FILES);readers=''.join(f'<details id="source-{n}"><summary>{n}</summary><pre><code>{escape((source/n).read_text())}</code></pre></details>' for n in FILES)
  page=f'''<!doctype html><html lang="{'en' if en else 'zh-CN'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'self'; style-src 'self'; connect-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'"><title>{title} · ModelAtlas</title><link rel="stylesheet" href="diffusion-noise-lab.css"><script src="diffusion-noise.js" defer></script><script src="diffusion-noise-fixtures.js" defer></script><script src="diffusion-noise-lab.js" defer></script></head><body><a class="skip" href="#noise-main">{t('跳至课程','Skip to lesson')}</a><header><a href="academy{suffix}.html#multimodal">ModelAtlas · {t('多模态机制','Multimodal mechanisms')}</a><nav aria-label="{t('语言','Language')}"><a data-noise-language href="diffusion-noise-lab.html">中文</a> · <a data-noise-language href="diffusion-noise-lab-en.html">English</a></nav></header><main id="noise-main"><p>MODELATLAS · MIX → INVERT → COMPARE → EXPLAIN</p><h1>{title}</h1><div class="warning">{prose(chunks[0].split(chr(10),1)[1])}</div><p>{t('语言与地区独立。本课无需厂商服务；导航只保留合法地区与共同章节，不保留输入和结果。','Language and region are independent. No provider service is needed; navigation retains valid region and shared section only, not inputs or results.')}</p><nav aria-label="{t('课程目录','Lesson sections')}"><a href="#worked">{t('跟做','Worked trace')}</a> · <a href="#interactive">{t('交互计算','Interactive calculation')}</a> · <a href="#transfer">{t('独立迁移','Independent transfer')}</a> · <a href="#downloads">{t('下载','Downloads')}</a></nav>{sections['contract']}{sections['worked']}{controls}{sections['run']}{sections['transfer']}<details id="reference"><summary>{t('独立尝试后展开 T 参考','Reveal T reference after your attempt')}</summary><pre>{reference}</pre></details>{sections['finish']}<section id="downloads"><h2>{t('完整源码材料包','Complete source packet')}</h2><p><a href="diffusion-noise-lab.zip" download>{t('下载标准库 Python 实验 ZIP','Download standalone Python lab ZIP')}</a></p><ul>{links}</ul>{readers}</section><footer><p>{t('来源核对','Sources checked')}: 2026-11-02 · <a href="https://arxiv.org/html/2006.11239v2">DDPM v2 · Eq. 4</a> · {t('首次投稿 2020-06-19，v2 2020-12-16，非商用模型发布日期。','First submitted 2020-06-19; v2 2020-12-16, not commercial model release dates.')}</p><p><a href="video-sampling-lab{suffix}.html">{t('下一步：视频抽帧与时序证据','Next: video sampling and temporal evidence')}</a> · <a href="tiny-training{suffix}.html">{t('什么才是训练？','What counts as training?')}</a></p></footer></main></body></html>'''
  (web/f'diffusion-noise-lab{suffix}.html').write_text(page)
if __name__=='__main__':render(Path(__file__).resolve().parents[1])
